  const t = "AAPL MSFT NVDA AMZN GOOGL GOOG META AVGO TSLA COST NFLX PLTR AMD ASML CSCO TMUS AZN LIN INTU ISRG PEP SHOP MU LRCX BKNG AMAT QCOM TXN PDD INTC ARM KLAC APP ADBE AMGN GILD HON CRWD PANW ADI CMCSA ADP SBUX MELI VRTX CEG MSTR ORLY CDNS SNPS DASH MRVL CTAS ABNB MAR FTNT REGN MDLZ PYPL WDAY ADSK CSX AEP ROP CHTR NXPI MNST PCAR TRI AXON FAST IDXX ZS PAYX DDOG TTWO EA ROST KDP BKR XEL EXC CCEP FANG ODFL CPRT KHC VRSK GEHC CTSH MCHP LULU CSGP TEAM WBD DXCM ON BIIB TTD CDW GFS ANSS".split(" ");
  const chunks = []; for (let i = 0; i < t.length; i += 25) chunks.push(t.slice(i, i + 25));
  const qs = await Promise.allSettled(chunks.map(c => quote({ tickers: c })));
  const rows: any[] = []; const errs: string[] = [];
  qs.forEach((q: any) => q.status === "fulfilled" ? rows.push(...q.value.data) : errs.push(String(q.reason).slice(0, 200)));
  const ns = await Promise.allSettled(["NVDA", "AAPL", "MSFT"].map(tk => news({ ticker: tk, limit: 8 })));
  return {
    errs,
    worst: rows.filter(r => r.changePercent != null).sort((a, b) => a.changePercent - b.changePercent).slice(0, 25).map(r => `${r.ticker} ${r.price} ${r.change} ${r.changePercent}% ${r.asOf}`),
    best: rows.filter(r => r.changePercent != null).sort((a, b) => b.changePercent - a.changePercent).slice(0, 5).map(r => `${r.ticker} ${r.changePercent}%`),
    n: rows.length,
    news: ns.map((x: any) => x.status === "fulfilled" ? x.value.data.map((a: any) => `${a.date.slice(0,16)} ${a.title} | ${a.url}`) : String(x.reason).slice(0, 200)),
  };
}
